public static void main(String[] args) {
    test("quote waits for all three inputs, in any completion order", () -> {
        var price = new CompletableFuture<BigDecimal>();
        var tax = new CompletableFuture<BigDecimal>();
        var discount = new CompletableFuture<BigDecimal>();
        var q = quote(price, tax, discount);
        tax.complete(d("0.25"));
        discount.complete(d("1.00"));
        ok(!q.isDone());
        price.complete(d("19.99"));
        eq(q.join().toPlainString(), "23.99");
    });
    test("a failed discount counts as zero", () -> {
        var discount = new CompletableFuture<BigDecimal>();
        var q = quote(CompletableFuture.completedFuture(d("10")), CompletableFuture.completedFuture(d("0.1")), discount);
        discount.completeExceptionally(new IllegalStateException("promo service down"));
        eq(q.join().toPlainString(), "11.00");
    });
    test("a failed price fails the quote with the same cause", () -> {
        var price = new CompletableFuture<BigDecimal>();
        var q = quote(price, CompletableFuture.completedFuture(d("0.1")), CompletableFuture.completedFuture(d("0")));
        var cause = new IllegalStateException("pricing down");
        price.completeExceptionally(cause);
        ok(q.isCompletedExceptionally());
        ok(failure(q) == cause);
    });
    test("allInOrder keeps input order whatever the completion order", () -> {
        var a = new CompletableFuture<String>();
        var b = new CompletableFuture<String>();
        var c = new CompletableFuture<String>();
        var all = allInOrder(List.of(a, b, c));
        c.complete("C");
        a.complete("A");
        ok(!all.isDone());
        b.complete("B");
        eq(all.join(), List.of("A", "B", "C"));
        eq(allInOrder(List.<CompletableFuture<String>>of()).join(), List.of());
    });
    test("allInOrder fails as soon as one input fails", () -> {
        var a = new CompletableFuture<String>();
        var b = new CompletableFuture<String>();
        var all = allInOrder(List.of(a, b));
        var cause = new IllegalArgumentException("bad sku");
        b.completeExceptionally(cause);
        ok(all.isCompletedExceptionally());
        ok(failure(all) == cause);
    });
    test("firstSuccess takes the first value and skips earlier failures", () -> {
        var a = new CompletableFuture<String>();
        var b = new CompletableFuture<String>();
        var c = new CompletableFuture<String>();
        var first = firstSuccess(List.of(a, b, c));
        a.completeExceptionally(new IllegalStateException("eu down"));
        ok(!first.isDone());
        c.complete("from us");
        b.complete("from asia");
        eq(first.join(), "from us");
    });
    test("firstSuccess fails only when every input has failed", () -> {
        var a = new CompletableFuture<String>();
        var b = new CompletableFuture<String>();
        var first = firstSuccess(List.of(a, b));
        a.completeExceptionally(new IllegalStateException("one"));
        ok(!first.isDone());
        b.completeExceptionally(new IllegalStateException("two"));
        eq(failure(first).getClass(), IllegalStateException.class);
        eq(failure(first).getMessage(), "all failed");
        eq(failure(firstSuccess(List.<CompletableFuture<String>>of())).getMessage(), "all failed");
    });
    test("withDeadline gives the fallback if the deadline fires first, else the value", () -> {
        var slow = new CompletableFuture<String>();
        var deadline = new CompletableFuture<Void>();
        var r = withDeadline(slow, deadline, "cached");
        deadline.complete(null);
        slow.complete("fresh");
        eq(r.join(), "cached");
        var fast = new CompletableFuture<String>();
        var later = new CompletableFuture<Void>();
        var r2 = withDeadline(fast, later, "cached");
        fast.complete("fresh");
        later.complete(null);
        eq(r2.join(), "fresh");
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("the buffer holds up to its capacity and hands items out FIFO", () -> {
        var b = new BoundedBuffer<String>(2);
        ok(b.offer("a"));
        ok(b.offer("b"));
        ok(!b.offer("c"));
        eq(b.poll(), Optional.of("a"));
        ok(b.offer("c"));
        eq(b.poll(), Optional.of("b"));
        eq(b.poll(), Optional.of("c"));
        eq(b.poll(), Optional.empty());
    });
    test("a capacity below 1 is refused", () -> {
        raises(IllegalArgumentException.class, () -> new BoundedBuffer<String>(0));
        eq(new BoundedBuffer<String>(1).offer("x"), true);
    });
    test("a fast producer waits while the buffer is full, keeping its item", () ->
        eq(simulate(2, 3, "PPPCPCC"), new SimResult(List.of(1, 2, 3), 1, 0)));
    test("a fast consumer waits while the buffer is empty", () ->
        eq(simulate(1, 1, "CPCC"), new SimResult(List.of(1), 0, 2)));
    test("producer steps after the last item are not waits", () -> {
        eq(simulate(1, 1, "PPPC"), new SimResult(List.of(1), 0, 0));
        eq(simulate(3, 2, "PPPPCCC"), new SimResult(List.of(1, 2), 0, 1));
    });
    test("a step that is not P or C is rejected", () ->
        raises(IllegalArgumentException.class, () -> simulate(1, 1, "PXC")));
    test("pipeline runs a real producer and consumer and keeps the order", () -> {
        var input = new ArrayList<Integer>();
        var doubled = new ArrayList<Integer>();
        for (int i = 1; i <= 1_000; i++) {
            input.add(i);
            doubled.add(2 * i);
        }
        eq(pipeline(input, 1, x -> x * 2), doubled);
    });
    test("pipeline passes through values a magic-number pill would clash with", () ->
        eq(pipeline(List.of(0, Integer.MIN_VALUE, Integer.MAX_VALUE, -1), 4, x -> x), List.of(0, Integer.MIN_VALUE, Integer.MAX_VALUE, -1)));
    test("pipeline with no input returns an empty list", () ->
        eq(pipeline(List.of(), 3, x -> x), List.of()));
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("nested acquisitions create held -> acquired edges", () ->
        eq(lockOrderGraph(Map.of("T1", List.of("+a", "+b", "+c", "-c", "-b", "-a"))),
            Map.of("a", Set.of("b", "c"), "b", Set.of("c"), "c", Set.of())));
    test("a released lock creates no edge", () ->
        eq(lockOrderGraph(Map.of("T1", List.of("+a", "-a", "+b", "-b"))), Map.of("a", Set.of(), "b", Set.of())));
    test("re-acquiring a held lock adds no edge and needs as many releases", () -> {
        eq(lockOrderGraph(Map.of("T1", List.of("+a", "+a", "-a", "+b", "-b", "-a"))),
            Map.of("a", Set.of("b"), "b", Set.of()));
        var e = raises(IllegalStateException.class, () -> lockOrderGraph(Map.of("T9", List.of("+a", "-a", "-a"))));
        eq(e.getMessage(), "T9 releases a it does not hold");
    });
    test("an op that is not + or - and a name is rejected", () -> {
        raises(IllegalArgumentException.class, () -> lockOrderGraph(Map.of("T1", List.of("a"))));
        raises(IllegalArgumentException.class, () -> lockOrderGraph(Map.of("T1", List.of("*a"))));
        raises(IllegalArgumentException.class, () -> lockOrderGraph(Map.of("T1", List.of("+"))));
    });
    test("two threads taking two locks in opposite orders form a cycle", () -> {
        var g = lockOrderGraph(Map.of("T1", List.of("+a", "+b", "-b", "-a"), "T2", List.of("+b", "+a", "-a", "-b")));
        eq(g, Map.of("a", Set.of("b"), "b", Set.of("a")));
        eq(findCycle(g), Optional.of(List.of("a", "b")));
    });
    test("findCycle starts the cycle at its smallest lock, or finds none", () -> {
        eq(findCycle(graph("a>d", "d>b", "b>c", "c>d")), Optional.of(List.of("b", "c", "d")));
        eq(findCycle(graph("x>y", "y>z", "x>z")), Optional.empty());
        eq(findCycle(graph("q>q")), Optional.of(List.of("q")));
    });
    test("safeOrder respects every edge, smallest available lock first", () -> {
        eq(safeOrder(graph("a>c", "b>c", "c>d", "e")), List.of("a", "b", "c", "d", "e"));
        eq(safeOrder(graph("z>a", "m")), List.of("m", "z", "a"));
    });
    test("safeOrder refuses a graph with a cycle and names it", () -> {
        var e = raises(IllegalStateException.class, () -> safeOrder(graph("b>a", "a>b", "c")));
        eq(e.getMessage(), "deadlock possible: a -> b -> a");
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

