            var m = new Metrics();
            eq(m.requests(), 0);
            var pool = Executors.newFixedThreadPool(4);
            try {
                var jobs = new ArrayList<Callable<Void>>();
                for (int t = 0; t < 4; t++) jobs.add(() -> {
                    for (int i = 1; i <= 10_000; i++) m.record(i % 100);
