                            var host = "w" + worker + "-" + i;
                            holder.update(c -> c.withHost(host));
                        }
                        return null;
                    });
                }
                for (var f : pool.invokeAll(jobs)) f.get();
            } finally {
                pool.shutdownNow();
            }
            var hosts = holder.current().hosts();
            eq(hosts.size(), 1_000);
            eq(new HashSet<>(hosts).size(), 1_000);
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

